  });

  it('afterSession fires when beforeSession throws', async () => {
    let afterSessionCalled = false;
    const hooks: OrchestratorHooks = {
      beforeSession: async () => {
        throw new Error('session init failed');
      },
      afterSession: async () => {
        afterSessionCalled = true;
      },
    };

    const orchestrator = createChatOrchestrator(createMockProvider('hi'), promptBuilder, undefined, {hooks});
    await orchestrator.processMessage(createSession('hello')).catch(() => {});

